/*
 * Identity Wallet — design tokens ("The Sealed Credential")
 * The single source of truth for color, type, space, and motion in the app.
 * Mirrors DESIGN.md / .impeccable/design.json at the repo root. Components
 * reference these custom properties via var(); never hardcode raw values.
 *
 * Colors are OKLCH — the brand's canonical color space.
 */
:root {
  /* ── Brand: the seal ──────────────────────────────────────────── */
  --color-primary: oklch(0.46 0.105 62);      /* sealing-wax gold — primary actions, brand mark */
  --color-primary-deep: oklch(0.38 0.09 60);  /* pressed / active gold */
  --color-accent: oklch(0.34 0.10 330);       /* aubergine — links, "reveal the machinery" affordances */
  --color-accent-deep: oklch(0.28 0.09 330);
  --color-seal-pale: oklch(0.92 0.055 80);    /* pale gold ground for sealed / verified marks (takes ink text) */
  --color-on-color: oklch(0.99 0.005 80);     /* near-white text on saturated fills */

  /* ── Neutral: archival paper & ink ────────────────────────────── */
  --color-bg: oklch(1 0 0);                   /* pure white — the seal & type carry the brand, not the surface */
  --color-surface: oklch(0.975 0.004 75);     /* sealed parchment — cards, panels */
  --color-surface-sunk: oklch(0.955 0.005 75);/* inset / nested panels */
  --color-ink: oklch(0.23 0.012 60);          /* body text & headings (≈13:1 on bg, AAA) */
  --color-ink-soft: oklch(0.31 0.012 60);     /* secondary prose that still must stay AAA (≈9:1) */
  --color-muted: oklch(0.42 0.012 60);        /* labels & metadata; body copy uses --color-ink */
  --color-line: oklch(0.90 0.004 75);         /* hairline borders & dividers — never a colored stripe */

  /* ── Status (signal only — always pair color with icon + label) ─ */
  --color-safe: oklch(0.40 0.10 150);
  --color-safe-surface: oklch(0.95 0.045 150);
  --color-warning: oklch(0.42 0.10 60);
  --color-warning-surface: oklch(0.95 0.055 75);
  --color-critical: oklch(0.44 0.16 25);
  --color-critical-surface: oklch(0.95 0.045 25);
  --color-critical-solid: oklch(0.52 0.20 25);/* solid alarm fill for the override CTA (takes --color-on-color) */
  --color-expired: oklch(0.42 0.02 25);       /* deliberately ashen — distinct from critical */
  --color-expired-surface: oklch(0.95 0.004 25);
  --color-info: oklch(0.42 0.07 250);
  --color-info-surface: oklch(0.95 0.03 250);

  /* ── Type families ────────────────────────────────────────────── */
  --font-display: 'Libre Caslon Display', Georgia, 'Times New Roman', serif; /* the signet — display moments only */
  --font-sans: 'Public Sans', system-ui, -apple-system, sans-serif;          /* the working voice */
  --font-mono: 'JetBrains Mono', ui-monospace, 'SF Mono', Menlo, monospace;  /* the literal truth — DIDs, keys */

  /* ── Type scale (fixed rem, ~1.2 ratio — never fluid clamp) ───── */
  --text-display: 1.75rem;   --leading-display: 1.15;
  --text-headline: 1.375rem; --leading-headline: 1.2;
  --text-title: 1.125rem;    --leading-title: 1.3;
  --text-body: 1rem;         --leading-body: 1.55;
  --text-label: 0.8125rem;   --leading-label: 1.3;
  --text-data: 0.875rem;     --leading-data: 1.5;
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  /* ── Spacing (4px base) ───────────────────────────────────────── */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;

  /* ── Radii ────────────────────────────────────────────────────── */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* ── Elevation (flat at rest; shadows only for floating surfaces) ─ */
  --shadow-sheet: 0 -8px 32px oklch(0.23 0.012 60 / 0.14);
  --shadow-toast: 0 4px 20px oklch(0.23 0.012 60 / 0.16);

  /* ── Motion (150–250ms, ease-out; state, not decoration) ──────── */
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --duration-fast: 120ms;
  --duration-base: 180ms;
  --duration-slow: 240ms;

  /* ── Z-index scale (semantic — never arbitrary 999s) ──────────── */
  --z-dropdown: 100;
  --z-sticky: 200;
  --z-modal-backdrop: 300;
  --z-modal: 400;
  --z-toast: 500;
  --z-tooltip: 600;
}

/*
 * Self-hosted brand fonts — bundled into dist/ for offline use.
 * A Tauri WKWebView loads from disk with no web server, and a security wallet
 * must never fetch fonts from a runtime CDN. Files live in static/fonts/ and are
 * copied to the build by adapter-static. See static/fonts/README.md for sources.
 */

/* Public Sans — the working voice (USWDS, OFL) */
@font-face {
  font-family: 'Public Sans';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/fonts/PublicSans-Regular.woff2') format('woff2');
}
@font-face {
  font-family: 'Public Sans';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url('/fonts/PublicSans-Medium.woff2') format('woff2');
}
@font-face {
  font-family: 'Public Sans';
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url('/fonts/PublicSans-SemiBold.woff2') format('woff2');
}
@font-face {
  font-family: 'Public Sans';
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url('/fonts/PublicSans-Bold.woff2') format('woff2');
}

/* JetBrains Mono — the literal truth: DIDs, keys, CIDs (OFL) */
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/fonts/JetBrainsMono-Regular.woff2') format('woff2');
}
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url('/fonts/JetBrainsMono-Medium.woff2') format('woff2');
}

/* Libre Caslon Display — the signet, for display moments only (OFL) */
@font-face {
  font-family: 'Libre Caslon Display';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/fonts/LibreCaslonDisplay-Regular.ttf') format('truetype');
}

/*
 * Base layer — global element defaults built on the tokens.
 * Imported once in the root layout, after tokens + fonts.
 */
*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  color-scheme: light; /* the app is light & humane by design — not Ledger-dark */
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: var(--weight-regular);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

a {
  color: var(--color-accent);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
}

/* AAA focus: a visible aubergine ring on every interactive element, never removed. */
:where(a, button, input, select, textarea, summary, [role='button'], [tabindex]):focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

::selection {
  background: var(--color-seal-pale);
  color: var(--color-ink);
}

/* Reduced motion is not optional. Collapse animation/transition to near-instant. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

