2	  import { onDestroy, onMount } from 'svelte';
3	  import LoadingScreen from './LoadingScreen.svelte';
4	  import { registerHandle, checkHandleResolution, type RegisterHandleError } from '$lib/ipc';
5	
6	  let {
7	    handleLabel,
8	    did,
9	    onsuccess,
10	    ontimeout,
11	  }: {
12	    /** The label portion of the handle (e.g. `"alice"`), collected earlier in onboarding. */
13	    handleLabel: string;
14	    /** The user's DID, used to verify HTTP resolution resolves to the correct identity. */
15	    did: string;
16	    /** Called when the handle registers and HTTP resolution confirms the DID. */
17	    onsuccess: (handle: string) => void;
18	    /**
19	     * Called when registration succeeded but HTTP resolution timed out after 2 minutes.
20	     * The handle is registered — DNS is just still propagating.
21	     * The caller should proceed and show a "still resolving" banner on the home screen.
22	     */
23	    ontimeout: (handle: string) => void;
24	  } = $props();
25	
26	  type Phase =
27	    | { kind: 'registering' }
28	    | { kind: 'polling'; handle: string }
29	    | { kind: 'error'; error: RegisterHandleError };
30	
31	  let phase = $state<Phase>({ kind: 'registering' });
32	
33	  const POLL_INTERVAL_MS = 4_000;
34	  const POLL_TIMEOUT_MS = 120_000;
35	
36	  let pollTimer: ReturnType<typeof setInterval> | undefined;
37	  let timeoutTimer: ReturnType<typeof setTimeout> | undefined;
38	  // Guard against the rare race where a poll tick resolves after the timeout fires.
39	  let settled = false;
40	
41	  function stopPolling() {
42	    if (pollTimer !== undefined) {
43	      clearInterval(pollTimer);
44	      pollTimer = undefined;
45	    }
46	    if (timeoutTimer !== undefined) {
47	      clearTimeout(timeoutTimer);
48	      timeoutTimer = undefined;
49	    }
50	  }
51	
52	  function startPolling(handle: string) {
53	    phase = { kind: 'polling', handle };
54	    settled = false;
55	
56	    pollTimer = setInterval(() => {
57	      checkHandleResolution(handle, did)
58	        .then((resolved) => {
59	          if (resolved && !settled) {
60	            settled = true;
61	            stopPolling();
62	            onsuccess(handle);
63	          }
64	        })
65	        .catch((err) => {
66	          console.error('[HandleRegistrationScreen] poll tick failed:', err);
67	        });
68	    }, POLL_INTERVAL_MS);
69	
70	    timeoutTimer = setTimeout(() => {
71	      if (!settled) {
72	        settled = true;
73	        stopPolling();
74	        ontimeout(handle);
75	      }
76	    }, POLL_TIMEOUT_MS);
77	  }
78	
79	  async function run() {
80	    phase = { kind: 'registering' };
81	    stopPolling();
82	
83	    try {
84	      const result = await registerHandle(handleLabel);
85	      startPolling(result.handle);
86	    } catch (raw: unknown) {
87	      console.error('[HandleRegistrationScreen] registerHandle failed:', raw);
88	      if (
89	        typeof raw === 'object' &&
90	        raw !== null &&
91	        'code' in raw &&
92	        typeof (raw as RegisterHandleError).code === 'string'
93	      ) {
94	        phase = { kind: 'error', error: raw as RegisterHandleError };
95	      } else {
96	        phase = { kind: 'error', error: { code: 'UNKNOWN', message: 'An unexpected error occurred.' } };
97	      }
98	    }
99	  }
100	
101	  function errorMessage(err: RegisterHandleError): string {
102	    switch (err.code) {
103	      case 'HANDLE_TAKEN':
104	        return 'That handle is already taken.';
105	      case 'INVALID_HANDLE':
106	        return 'The handle format is invalid. Please go back and choose another.';
107	      case 'DNS_ERROR':
108	        return 'Handle registered, but DNS setup failed. Please contact support.';
109	      case 'NO_DOMAINS':
110	        return 'The relay has no handle domains configured. Please contact support.';
111	      case 'SESSION_EXPIRED':
112	        return 'Your session has expired. Please sign in again to continue.';
113	      case 'KEYCHAIN_ERROR':
114	        return "Couldn't read your credentials. Please restart the app and try again.";
115	      case 'NETWORK_ERROR':
116	      default:
117	        return "Couldn't reach the server. Check your connection.";
118	    }
119	  }
120	
121	  function canRetry(err: RegisterHandleError): boolean {
122	    return (
123	      err.code !== 'INVALID_HANDLE' &&
124	      err.code !== 'DNS_ERROR' &&
125	      err.code !== 'NO_DOMAINS' &&
126	      err.code !== 'SESSION_EXPIRED'
127	    );
128	  }
129	
130	  onMount(() => run());
131	  onDestroy(() => stopPolling());
