30	  // ── Onboarding step type ─────────────────────────────────────────────────
31	  //
32	  // Design plan originally specified an 'error' state for displaying errors,
33	  // but the implementation uses per-screen error rewinding instead.
34	  // When an error occurs (e.g., EXPIRED_CODE, EMAIL_TAKEN), the app rewinds
35	  // to the relevant screen and displays an inline error message below the
36	  // input field, rather than showing a separate error screen. This is a better
37	  // UX pattern — users can immediately correct the issue on the same screen
38	  // instead of navigating through an extra modal. No 'error' step is needed.
39	
40	  type OnboardingStep =
41	    | 'mode_select'
42	    | 'relay_config'
43	    | 'welcome'
44	    | 'claim_code'
45	    | 'email'
46	    | 'handle'
