12	/// Build an OAuth error redirect (303) to `redirect_uri` with error parameters.
13	pub(super) fn error_redirect(
14	    redirect_uri: &str,
15	    error: &str,
16	    description: &str,
17	    state: &str,
18	) -> Redirect {
19	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
20	    let url = format!(
21	        "{}{}error={}&error_description={}&state={}",
22	        redirect_uri,
23	        sep,
24	        encode_param(error),
25	        encode_param(description),
26	        encode_param(state),
27	    );
28	    Redirect::to(&url)
29	}
