140	/// Percent-encode a string for safe inclusion as a URL query parameter value.
141	pub(super) fn encode_param(s: &str) -> String {
142	    let mut out = String::with_capacity(s.len());
143	    for b in s.bytes() {
144	        match b {
145	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
146	                out.push(b as char)
147	            }
148	            _ => out.push_str(&format!("%{b:02X}")),
149	        }
150	    }
151	    out
152	}
