154	/// HTML-escape a string for safe embedding in HTML content or attribute values.
155	pub(super) fn html_escape(s: &str) -> String {
156	    s.replace('&', "&amp;")
157	        .replace('<', "&lt;")
158	        .replace('>', "&gt;")
159	        .replace('"', "&quot;")
160	        .replace('\'', "&#39;")
161	}
